      const c = 1 / Math.sqrt(1 + t * t);
      const s = t * c;
      const app = A[p][p];
      const aqq = A[q][q];

      for (let k = 0; k < n; k++) {
        if (k === p || k === q) continue;
        const akp = A[k][p];
        const akq = A[k][q];
        const np = c * akp - s * akq;
        const nq = s * akp + c * akq;
        A[k][p] = A[p][k] = np;
        A[k][q] = A[q][k] = nq;
      }

      A[p][p] = app - t * apq;
      A[q][q] = aqq + t * apq;
      A[p][q] = A[q][p] = 0;

      for (let k = 0; k < n; k++) {
        const bkp = B[k][p];
        const bkq = B[k][q];
        B[k][p] = c * bkp - s * bkq;
        B[k][q] = s * bkp + c * bkq;
