  function runCMA(start, sigma0, budget) {
    if (budget <= 0 || remaining() <= 0) return;

    const lambda = 20;
    const mu = 10;
    const weights = new Array(mu);
    let weightSum = 0;
    for (let i = 0; i < mu; i++) {
      weights[i] = Math.log(mu + 0.5) - Math.log(i + 1);
      weightSum += weights[i];
    }
    for (let i = 0; i < mu; i++) weights[i] /= weightSum;

    let sumW2 = 0;
    for (let i = 0; i < mu; i++) sumW2 += weights[i] * weights[i];
    const mueff = 1 / sumW2;

    const cc = (4 + mueff / n) / (n + 4 + 2 * mueff / n);
    const cs = (mueff + 2) / (n + mueff + 5);
    const c1 = 2 / (Math.pow(n + 1.3, 2) + mueff);
    const cmu = Math.min(
      1 - c1,
      2 * (mueff - 2 + 1 / mueff) / (Math.pow(n + 2, 2) + mueff)
    );
    const damps =
      1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (n + 1)) - 1) + cs;
    const chiN = Math.sqrt(n) *
      (1 - 1 / (4 * n) + 1 / (21 * n * n));

    let m = start.slice();
    for (let j = 0; j < n; j++) {
      if (j === 6) m[j] = mod(m[j], 1);
      else m[j] = reflect01(m[j]);
    }

    let sigma = sigma0;
    let pc = new Array(n).fill(0);
    let ps = new Array(n).fill(0);
    let C = new Array(n);
    for (let i = 0; i < n; i++) {
      C[i] = new Array(n).fill(0);
      C[i][i] = 1;
    }

    let localEvals = 0;
    let generation = 0;

    while (localEvals < budget) {
      const count = Math.min(lambda, budget - localEvals, remaining());
      if (count <= 0) break;

      const eig = eigSym(C);
      const B = eig.B;
      const D = eig.D;
      const candidates = [];

      for (let k = 0; k < count; k++) {
        let raw;
        if (generation === 0 && k === 0) {
          raw = m.slice();
        } else {
          const z = new Array(n);
          for (let j = 0; j < n; j++) z[j] = normal();
          const scaled = new Array(n);
          for (let j = 0; j < n; j++) scaled[j] = D[j] * z[j];

          raw = new Array(n);
          for (let i = 0; i < n; i++) {
            let step = 0;
            for (let j = 0; j < n; j++) {
              step += B[i][j] * scaled[j];
            }
            raw[i] = m[i] + sigma * step;
          }
        }

        const x = new Array(n);
        for (let j = 0; j < n; j++) {
          x[j] = j === 6 ? mod(raw[j], 1) : reflect01(raw[j]);
        }

        const score = evaluate(x);
        candidates.push({ x: x, score: score });
      }

      localEvals += count;
      if (candidates.length < mu) break;
      candidates.sort((a, b) => b.score - a.score);

      const oldM = m.slice();
      const newM = new Array(n);
      const yw = new Array(n);
      for (let j = 0; j < n; j++) {
        let step = 0;
        for (let k = 0; k < mu; k++) {
          step += weights[k] *
            difference(candidates[k].x[j], oldM[j], j);
        }
        yw[j] = step / sigma;
        const v = oldM[j] + step;
        newM[j] = j === 6 ? mod(v, 1) : reflect01(v);
      }

      const whitened = new Array(n).fill(0);
      for (let k = 0; k < n; k++) {
        let dot = 0;
        for (let i = 0; i < n; i++) dot += B[i][k] * yw[i];
        dot /= D[k];
        for (let i = 0; i < n; i++) whitened[i] += B[i][k] * dot;
      }

      for (let j = 0; j < n; j++) {
        ps[j] = (1 - cs) * ps[j] +
          Math.sqrt(cs * (2 - cs) * mueff) * whitened[j];
      }

      let normPS = 0;
      for (let j = 0; j < n; j++) normPS += ps[j] * ps[j];
      normPS = Math.sqrt(normPS);

      const correction = Math.sqrt(
        1 - Math.pow(1 - cs, 2 * (generation + 1))
      );
      const hsig = normPS / Math.max(1e-12, correction) / chiN <
        1.4 + 2 / (n + 1);

      for (let j = 0; j < n; j++) {
        pc[j] = (1 - cc) * pc[j] +
          (hsig ? 1 : 0) * Math.sqrt(cc * (2 - cc) * mueff) * yw[j];
      }

      const ys = new Array(mu);
      for (let k = 0; k < mu; k++) {
        ys[k] = new Array(n);
        for (let j = 0; j < n; j++) {
          ys[k][j] =
            difference(candidates[k].x[j], oldM[j], j) / sigma;
        }
      }

      const factor = 1 - c1 - cmu +
        c1 * (hsig ? 0 : 1) * cc * (2 - cc) * mueff;
      const nextC = new Array(n);
      for (let i = 0; i < n; i++) {
        nextC[i] = new Array(n);
        for (let j = 0; j < n; j++) {
          let rankMu = 0;
          for (let k = 0; k < mu; k++) {
            rankMu += weights[k] * ys[k][i] * ys[k][j];
          }
          nextC[i][j] = factor * C[i][j] +
            c1 * pc[i] * pc[j] +
            cmu * rankMu;
        }
      }
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          const v = 0.5 * (nextC[i][j] + nextC[j][i]);
          nextC[i][j] = v;
          nextC[j][i] = v;
        }
      }

      m = newM;
      C = nextC;

      let exponent = (cs / damps) * (normPS / chiN - 1);
      exponent = clamp(exponent, -0.5, 0.5);
      sigma = clamp(sigma * Math.exp(exponent), 0.035, 0.55);
      generation++;
    }
  }

  const seedX = seeds.map(encode);
  for (let i = 0; i < seedX.length && remaining() > 0; i++) {
    evaluate(seedX[i]);
  }

  if (remaining() > 0) {
    const baseX = seedX[0].slice();
    const r = remaining();
    const firstBudget = Math.floor(r / 40) * 20;
    if (firstBudget > 0) runCMA(baseX, 0.22, firstBudget);
    const restart = bestX ? bestX.slice() : baseX;
    runCMA(restart, 0.14, remaining());
  }

  return bestParams || seeds[0].slice();
}

function policy(obs, params, mem) {
