  const hipD = clamp(par(8, 0.08), 0, 0.26);
  const kneeP = clamp(par(9, 1.8), 0.8, 3.8);
  const kneeD = clamp(par(10, 0.08), 0, 0.26);
  const bodyP = clamp(par(11, 0.62), 0.10, 1.5);
  const bodyD = clamp(par(12, 0.28), 0.03, 0.85);
  const obstacleGain = clamp(par(13, 1.3), 0, 4);
  const velocityCoupling = clamp(par(14, -0.04), -0.18, 0.12);
  const heightTarget = clamp(par(15, 1.08), 0.88, 1.30);
  const heightGain = clamp(par(16, 0.25), 0, 0.90);
  const phaseSync = clamp(par(17, 0.20), 0, 0.45);
  const leanTarget = clamp(par(18, -0.04), -0.12, 0.06);
  const contactHold = clamp(par(19, 0.20), 0, 0.85);
