      clamp(hipTarget, -0.88, 1.18),
      clamp(kneeTarget, -1.67, -0.055),
      hipVel,
      kneeVel
    ];
  }

  const a = targets(phase, footA);
  const b = targets(phase + 0.5, footB);

  const bodyCmd = clamp(
    bodyP * (1 + 0.15 * late) * (angle - leanTarget) +
    bodyD * (1 + 0.10 * late) * spin,
    -0.95,
    0.95
  );
