  const hipA = clamp(
    gaitScale * (
      hipP * (a[0] - read(5, 0)) +
      hipD * (a[2] - read(6, 0))
    ) + bodyCmd,
    -1,
    1
  );
  const kneeA = clamp(
    kneeP * (a[1] - read(7, -0.15)) +
    kneeD * (a[3] - read(8, 0)),
    -1,
    1
