  const legOffset = clamp(par(18, 0.50), 0.42, 0.58);
  const stepGain = clamp(par(19, 0.28), -0.8, 0.8);
  const speedStep = clamp(par(20, 0), -0.6, 0.6);
  const autoFlip = clamp(par(21, 0), 0, 1);

