  const par = (i, d) => {
    const v = Number(pp[i]);
    return Number.isFinite(v) ? v : d;
  };

  const period = clamp(par(0, 0.70), 0.48, 1.05);
  const hipAmp = clamp(par(1, 0.42), -0.72, 0.72);
  const hipBias = clamp(par(2, 0), -0.16, 0.16);
  const duty = clamp(par(3, 0.60), 0.48, 0.72);
  const kneeBase = clamp(par(4, 0.14), 0.03, 0.32);
  const kneeFlex = clamp(par(5, 0.75), 0.15, 1.35);
  const phase0 = mod(par(6, 0), 1);

  const hipP = clamp(par(7, 1.9), 0.55, 3.5);
  const hipD = clamp(par(8, 0.08), 0, 0.28);
  const kneeP = clamp(par(9, 1.8), 0.55, 3.5);
  const kneeD = clamp(par(10, 0.08), 0, 0.28);
  const bodyP = clamp(par(11, 0.55), 0.05, 1.4);
  const bodyD = clamp(par(12, 0.25), 0, 0.9);
  const leanTarget = clamp(par(13, -0.05), -0.16, 0.08);
  const heightTarget = clamp(par(14, 1.08), 0.94, 1.22);
  const heightGain = clamp(par(15, 0.25), 0, 0.9);
  const obstacleGain = clamp(par(16, 1.6), 0, 3.5);
  const phaseSync = clamp(par(17, 0.08), 0, 0.4);
  const stepGain = clamp(par(18, -0.25), -0.8, 0.8);
  const speedStep = clamp(par(19, -0.05), -0.5, 0.5);
  const contactHold = clamp(par(20, 0.18), 0, 0.7);
  const legOffset = clamp(par(21, 0.50), 0.43, 0.59);

  const angle = read(0, 0);
  const spin = read(1, 0);
  const vx = read(2, 0);
  const vy = read(3, 0);
  const height = read(4, 1.05);
  const footA = read(9, 0) > 0.5;
  const footB = read(14, 0) > 0.5;
  const t = read(19, 0);

  let dt = 1 / 60;
  let phase;
  let vFilt;

  if (!Number.isFinite(mem._phase) || !Number.isFinite(mem._time)) {
    phase = phase0;
    vFilt = vx;
    mem._phase = phase;
    mem._time = t;
    mem._footA = footA;
    mem._footB = footB;
    mem._vfilt = vx;
  } else {
    let elapsed = t - mem._time;
    if (!Number.isFinite(elapsed) || elapsed <= 0) elapsed = 1 / 60;
    dt = clamp(elapsed, 1 / 240, 0.06);

    phase = mod(mem._phase + dt / period, 1);

    const oldV = Number.isFinite(mem._vfilt) ? mem._vfilt : vx;
    vFilt = oldV + (vx - oldV) * clamp(dt / 0.25, 0, 1);
    mem._vfilt = vFilt;

    let correction = 0;
    let events = 0;
    if (footA && !mem._footA) {
      correction += wrap(-phase);
      events++;
    }
    if (footB && !mem._footB) {
      correction += wrap(-mod(phase + legOffset, 1));
      events++;
    }
    if (events > 0) {
      phase = mod(
        phase + phaseSync * clamp(correction / events, -0.35, 0.35),
        1
      );
    }

    mem._phase = phase;
    mem._time = t;
    mem._footA = footA;
    mem._footB = footB;
  }

  phase = mod(mem._phase, 1);
  if (!Number.isFinite(vFilt)) vFilt = vx;

  const ahead1 = read(15, 0);
  const ahead2 = read(16, 0);
  const ahead3 = read(17, 0);
  const ahead4 = read(18, 0);
  const terrainUp = clamp(Math.max(
    0,
    ahead1,
    0.78 * ahead2,
    0.50 * ahead3,
    0.25 * ahead4
  ), 0, 0.35);
  const terrainDown = clamp(Math.max(
    0,
    -ahead1,
    -0.78 * ahead2,
    -0.50 * ahead3,
    -0.25 * ahead4
  ), 0, 0.25);

