    heightGain * (heightTarget - height) - 0.055 * vy,
    -0.30,
    0.30
  );

  function targets(q0, foot) {
    let q = mod(q0, 1);
    let phaseFactor = 1;

    if (foot && q >= duty) {
      const remain = 1 - contactHold;
      q = duty + (q - duty) * remain;
      phaseFactor = remain;
    }

    const inStance = q < duty;
    let hipShape;
    let swing = 0;
    let hipVel = 0;
    let kneeVel = 0;

    if (inStance) {
      const u = q / duty;
      const s = Math.sin(Math.PI * u);
      hipShape = Math.cos(Math.PI * u);
      hipVel = ampDot * hipShape -
        ampNow * Math.PI * s * cycleRate / duty * phaseFactor;
    } else {
      const u = clamp((q - duty) / (1 - duty), 0, 1);
      const s = Math.sin(Math.PI * u);
      hipShape = -Math.cos(Math.PI * u);
      swing = s;
      hipVel = ampDot * hipShape +
        ampNow * Math.PI * s * cycleRate / (1 - duty) * phaseFactor;
      kneeVel = -flexDot * swing -
        flexNow * Math.PI * Math.cos(Math.PI * u) *
        cycleRate / (1 - duty) * phaseFactor;
    }

    let hipTarget = hipBias + ampNow * hipShape;
    let kneeTarget = -kneeBase - flexNow * swing;

    if (!inStance && !foot) {
      const tilt = clamp(
        angle - leanTarget + 0.14 * spin,
        -0.85,
        0.85
      );
      const speedError = clamp(vFilt - 1.1, -1.5, 1.5);
      const placement = clamp(
        stepGain * tilt + speedStep * speedError,
        -0.55,
        0.55
      );
      hipTarget += placement * (0.20 + 0.80 * swing);

      const lift = obstacleGain * terrainUp;
      kneeTarget -= lift * (0.18 + 0.82 * swing);
      kneeTarget += 0.45 * terrainDown * (0.18 + 0.82 * swing);
    }

    let hc = heightCorrection;
    if (!inStance) hc *= 0.16;
    kneeTarget += hc;

    hipVel = clamp(hipVel, -5.9, 5.9);
    kneeVel = clamp(kneeVel, -8.1, 8.1);

