    if (kneeTarget < -1.67 || kneeTarget > -0.055) kneeVel = 0;

    return [
      clamp(hipTarget, -0.88, 1.18),
      clamp(kneeTarget, -1.67, -0.055),
      hipVel,
      kneeVel
    ];
  }

  const a = targets(phase, footA);
  const b = targets(phase + legOffset, footB);

  const bodyCmd = clamp(
    bodyP * (angle - leanTarget) + bodyD * spin,
    -0.94,
    0.94
  );
  const gaitScale = 1 - 0.18 * Math.abs(bodyCmd);

  return [
    clamp(
      gaitScale * (
        hipP * (a[0] - read(5, 0)) +
        hipD * (a[2] - read(6, 0))
      ) + bodyCmd,
      -1,
      1
    ),
    clamp(
      kneeP * (a[1] - read(7, -0.14)) +
      kneeD * (a[3] - read(8, 0)),
      -1,
      1
    ),
    clamp(
      gaitScale * (
        hipP * (b[0] - read(10, 0)) +
        hipD * (b[2] - read(11, 0))
      ) + bodyCmd,
      -1,
      1
    ),
    clamp(
      kneeP * (b[1] - read(12, -0.14)) +
      kneeD * (b[3] - read(13, 0)),
      -1,
      1
    )
  ];
}

