  let probes = [];
  let catBest = [null, null, null, null];
  let phases = [0, 0.25, 0.5, 0.75];
  let duties = [0.42, 0.58];
  let amps = [1, 0.7];

  for (let si = 0; si < 2; si++) {
    let s = si === 0 ? 1 : -1;
    for (let oi = 0; oi < 2; oi++) {
      let off = oi === 0 ? 0 : 0.5;
      let cat = si * 2 + oi;
      for (let pi = 0; pi < phases.length; pi++) {
        for (let di = 0; di < duties.length; di++) {
          for (let ai = 0; ai < amps.length; ai++) {
            if (count >= MAX_TRIALS - 100) break;
            let sem = base.slice();
            let amp = amps[ai];
            sem[4] = base[4] * s * amp;
            sem[5] = base[5] * s * amp;
            sem[6] = base[6] * s * amp;
            sem[1] = off;
            sem[2] = duties[di];
            sem[3] = phases[pi];
            let item = ev(toRaw(sem));
            if (item) {
              probes.push(item);
              if (!catBest[cat] || item.score > catBest[cat].score) {
                catBest[cat] = item;
              }
            }
          }
        }
      }
    }
  }

  let seeds = [];
  function addSeed(item) {
    if (!item || seeds.length >= 6) return;
    for (let i = 0; i < seeds.length; i++) {
      if (rawDist(seeds[i].raw, item.raw) < 1.0) return;
    }
    seeds.push(item);
  }

  for (let c = 0; c < 4; c++) addSeed(catBest[c]);

  let sortedProbes = probes.slice();
  sortedProbes.sort(function (a, b) { return b.score - a.score; });
  for (let i = 0; i < sortedProbes.length; i++) addSeed(sortedProbes[i]);

  if (!seeds.length) {
    let it = ev(DEFAULT_RAW);
    if (it) addSeed(it);
  }
  if (!seeds.length) {
    let it = ev(DEFAULT_RAW);
    if (it) seeds.push(it);
  }

  let islands = [];
  for (let s = 0; s < seeds.length && s < 6; s++) {
    let sig = new Array(D);
    for (let i = 0; i < D; i++) {
      if (i < 9) sig[i] = 0.24;
      else if (i < 17) sig[i] = 0.18;
      else sig[i] = 0.22;
    }
    islands.push({
      mean: seeds[s].raw.slice(),
      sigma: sig,
      best: seeds[s],
      stall: 0
    });
  }

  let gen = 0;
  let maxCem = MAX_TRIALS - 28;

  while (count < maxCem && gen < 35) {
    for (let ii = 0; ii < islands.length && count < maxCem; ii++) {
      let is = islands[ii];
      let N = 12;
      let cands = [];

      for (let j = 0; j < N && count < maxCem; j++) {
        let x;
        if (j === 0) {
          x = is.mean.slice();
        } else {
          x = new Array(D);
          for (let i = 0; i < D; i++) {
            let sd = is.sigma[i];
            if (gen % 4 === 3) sd *= 1.5;
            x[i] = clamp(is.mean[i] + sd * randn(), -1, 1);
          }
        }
        let item = ev(x);
        if (item) {
          cands.push({ x: item.raw, item: item });
