      }

      if (!cands.length) continue;
      cands.sort(function (a, b) { return b.item.score - a.item.score; });

      let isImproved = false;
      if (!is.best || cands[0].item.score > is.best.score) {
        is.best = cands[0].item;
        is.stall = 0;
        isImproved = true;
      } else {
        is.stall++;
      }

      let k = Math.max(2, Math.floor(cands.length * 0.3));
      if (k > cands.length) k = cands.length;
      let weights = [];
      let sumW = 0;
      for (let j = 0; j < k; j++) {
        let w = Math.log(k + 1) - Math.log(j + 1);
        weights.push(w);
        sumW += w;
      }

      let newMean = new Array(D);
      for (let i = 0; i < D; i++) newMean[i] = 0;
      for (let j = 0; j < k; j++) {
        let w = weights[j];
        let x = cands[j].x;
        for (let i = 0; i < D; i++) newMean[i] += w * x[i];
      }
