      }

      if (is.stall > 2) {
        for (let i = 0; i < D; i++) {
          newSigma[i] = Math.min(0.7, newSigma[i] * 1.18 + 0.012);
        }
        is.stall = 0;
      }

      is.mean = newMean;
      is.sigma = newSigma;
    }
    gen++;
