    mem.lastT = obs[19];
    let ph0 = (params && isFinite(params.testPhase)) ? params.testPhase : 0;
    mem.phase = mem.p[2] * 0.5 + ph0;
    mem.phase -= Math.floor(mem.phase);
    mem.heightOff = (params && isFinite(params.testHeight)) ? params.testHeight : 0;
    mem.angleOff = (params && isFinite(params.testAngle)) ? params.testAngle : 0;
    mem.prevContA = obs[9] > 0.5;
    mem.prevContB = obs[14] > 0.5;
    mem.vxF = obs[2];
  }
  let p = mem.p;
  let t = obs[19];
  let dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.3) dt = 1 / 60;
  mem.lastT = t;

  let alpha = 1 - Math.exp(-dt / 0.10);
  if (!isFinite(alpha)) alpha = 0.1;
  mem.vxF += alpha * (obs[2] - mem.vxF);
  if (!isFinite(mem.vxF)) mem.vxF = obs[2];
  let vxF = mem.vxF;

  let angle = obs[0];
  let spin = obs[1];
  let vy = obs[3];
  let height = obs[4];

  let contA = obs[9] > 0.5;
  let contB = obs[14] > 0.5;

  if (t > 0.35) {
    let corr = 0, cnt = 0;
    if (contA && !mem.prevContA) {
      let q = mem.phase;
      q -= Math.floor(q);
      corr += q - Math.round(q);
      cnt++;
    }
    if (contB && !mem.prevContB) {
      let q = mem.phase + p[1];
      q -= Math.floor(q);
      corr += q - Math.round(q);
      cnt++;
    }
    if (cnt > 0) {
      mem.phase -= (p[26] * corr) / cnt;
      mem.phase -= Math.floor(mem.phase);
    }
  }
  mem.prevContA = contA;
  mem.prevContB = contB;

  let safe = smoothstep(clamp((t - 8.6) / 1.0, 0, 1));
  let runUntil = p[24];
  let stopDur = Math.max(0.25, p[25]);
  let active = 1;
  if (t > runUntil) active = clamp(1 - (t - runUntil) / stopDur, 0, 1);
  if (t > 9.7) active = 0;
  let ramp = smoothstep(clamp(t / 0.55, 0, 1));
  let gaitW = clamp(active * ramp * (1 - safe), 0, 1);
  if (!isFinite(gaitW)) gaitW = 0;

  let targetAngle = p[18] * active * (1 - safe) + mem.angleOff * (1 - safe);
  let targetVel = p[17] * active * (1 - safe);
  let targetHeight = p[19] + mem.heightOff;

  let freq = p[0] + p[27] * Math.max(0, vxF);
  freq = clamp(freq, 0.2, 4.0);

  let obst = Math.max(
    0,
    obs[15] || 0,
    0.9 * (obs[16] || 0),
    0.65 * (obs[17] || 0),
    0.35 * (obs[18] || 0)
  );

  let out = [0, 0, 0, 0];

  for (let leg = 0; leg < 2; leg++) {
    let off = leg === 0 ? 0 : p[1];
    let q = mem.phase + off;
    q -= Math.floor(q);
    let stancePhase = q < p[2];
    let u = 0, u2, hGait, kGait;

    if (stancePhase) {
      u = p[2] > 1e-6 ? q / p[2] : 0;
      u = clamp(u, 0, 1);
      let sm = smoothstep(u);
      hGait = p[3] + (p[4] - p[3]) * sm;
      kGait = p[6] - p[7] * Math.sin(Math.PI * u);
    } else {
      u2 = (q - p[2]) / Math.max(1e-6, 1 - p[2]);
      u2 = clamp(u2, 0, 1);
      let sm = smoothstep(u2);
      let sw = Math.sin(Math.PI * u2);
      hGait = p[4] + (p[3] - p[4]) * sm + p[5] * sw;
      kGait = p[6] - p[8] * sw;
    }

    let stance = safe > 0.5 ? true : stancePhase;

    let hDes = hGait * gaitW;
    let kDes = p[28] + (kGait - p[28]) * gaitW;

    let velErr = vxF - targetVel;
    velErr = clamp(velErr, -4, 4);
    let placeScale = stance ? 0.35 : 1.0;
    let gp = 1 - safe;
    hDes += p[16] * velErr * placeScale * gp;
    hDes += p[15] * (targetAngle - angle) * (stance ? 0.6 : 1.0) * gp;

    if (!stancePhase && u2 !== undefined) {
      let sw = Math.sin(Math.PI * u2);
      if (sw > 0) {
        hDes += p[23] * obst * sw * gaitW;
        kDes -= p[22] * obst * sw * gaitW;
      }
    }

    let foot = leg === 0 ? contA : contB;
    if (gaitW > 0.03) {
      if (!stancePhase && foot) kDes -= 0.16 * gaitW;
      if (stancePhase && !foot) kDes += 0.08 * gaitW;
    }

    let cw = foot ? 1.0 : 0.25;
    kDes += p[20] * (targetHeight - height) * cw;
    kDes += -p[21] * vy * cw;

    hDes = clamp(hDes, -0.9, 1.2);
    kDes = clamp(kDes, -1.7, -0.05);

    let hip = obs[leg === 0 ? 5 : 10];
    let hipS = obs[leg === 0 ? 6 : 11];
    let knee = obs[leg === 0 ? 7 : 12];
    let kneeS = obs[leg === 0 ? 8 : 13];

    let uHip = p[9] * (hDes - hip) - p[10] * hipS;
    let uKnee = p[11] * (kDes - knee) - p[12] * kneeS;
    let bal = p[13] * (angle - targetAngle) + p[14] * spin;
    uHip += bal;

    if (!isFinite(uHip)) uHip = 0;
    if (!isFinite(uKnee)) uKnee = 0;

    out[2 * leg] = clamp(uHip, -1, 1);
    out[2 * leg + 1] = clamp(uKnee, -1, 1);
  }

  mem.phase += freq * dt;
  mem.phase -= Math.floor(mem.phase);
  if (!isFinite(mem.phase)) mem.phase = 0;

  return out;
}

function learn(lab) {
  const MAX_TRIALS = 995;
  let used = 0;
  let cache = Object.create(null);
  let all = [];

  function remaining() {
    try {
      if (lab && lab.trialsLeft) return lab.trialsLeft();
    } catch (e) {}
    return MAX_TRIALS - used;
  }

  function randn() {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  function rawKey(v) {
    let s = "";
    for (let i = 0; i < D; i++) s += v[i].toFixed(5) + ",";
    return s;
  }

  function extraKey(extra) {
    if (!extra) return "";
    let s = "";
    if (isFinite(extra.testPhase)) s += "p" + extra.testPhase.toFixed(5);
    if (isFinite(extra.testHeight)) s += "h" + extra.testHeight.toFixed(5);
    if (isFinite(extra.testAngle)) s += "a" + extra.testAngle.toFixed(5);
    return s;
  }

  function evalRaw(raw, extra) {
    if (used >= MAX_TRIALS) return null;
    if (remaining() <= 0) return null;

    let v = new Array(D);
    for (let i = 0; i < D; i++) {
      let x = (raw && i < raw.length) ? raw[i] : DEFAULT_RAW[i];
      if (!isFinite(x)) x = DEFAULT_RAW[i];
      v[i] = clamp(x, -1, 1);
    }

    let key = extraKey(extra) + "|" + rawKey(v);
    if (cache[key]) return cache[key];

    let params = { v: v };
    if (extra) {
      for (let k in extra) params[k] = extra[k];
    }

    let res = null;
    try {
      res = lab.trial(params);
    } catch (e) {
      res = null;
    }
    used++;

    let dist = 0, outcome = "error", time = 0, energy = 0;
    if (res) {
      if (isFinite(res.distance)) dist = Math.max(0, res.distance);
      if (res.outcome) outcome = res.outcome;
      if (isFinite(res.time)) time = clamp(res.time, 0, 10);
      if (isFinite(res.energy)) energy = res.energy;
    }

    let invalid = outcome === "invalid" || outcome === "error";
    let fin = outcome === "finished" || (time >= 9.999 && !invalid);
    let item = {
      raw: v.slice(),
      dist: dist,
      outcome: outcome,
      time: time,
      energy: energy,
      finished: fin,
      valid: !invalid,
      extra: extra ? true : false
    };
    cache[key] = item;
    all.push(item);
    return item;
  }

  function fit(item, mode) {
    if (!item || !item.valid) return -1e9;
    let d = item.dist;
    let t = item.time;
    let fin = item.finished;
    if (mode === 0) {
      return (fin ? 1000 : 0) + d + (fin ? 0 : 0.01 * t);
    }
    if (mode === 1) {
      return d + (fin ? 8 : 0) + 0.10 * t;
    }
    if (mode === 2) {
      return d + (fin ? 25 : 0) + 0.05 * t;
    }
    if (mode === 3) {
      return (fin ? 5000 : 0) + d;
    }
    return (fin ? 1000 : 0) + d;
  }

  function scoreOf(it) {
    if (!it || !it.valid) return 0;
    return it.dist;
  }

  function seedFrom(over) {
    let a = DEF_SEM.slice();
    for (let k in over) {
      let idx = +k;
      if (idx >= 0 && idx < D) a[idx] = over[k];
    }
    return a;
  }

  let seedSems = [];
  seedSems.push(DEF_SEM.slice());
  seedSems.push(seedFrom({
    1: 0.0, 3: 0.0, 4: 0.0, 5: 0.0, 7: 0.0, 8: 0.0,
    16: 0.0, 17: 0.0, 18: 0.0, 24: 4.0, 25: 0.3,
    6: -0.12, 28: -0.12
  }));
  seedSems.push(seedFrom({
    1: 0.0, 2: 0.55, 3: 0.20, 4: -0.20, 5: 0.10,
    6: -0.25, 7: 0.25, 8: 0.55, 0: 1.6,
    17: 1.2, 18: -0.05, 24: 7.5, 25: 0.9,
    16: 0.6, 15: 0.8, 19: 1.13
  }));
  seedSems.push(seedFrom({
    1: 0.5, 2: 0.70, 3: 0.30, 4: -0.30, 5: 0.10,
    6: -0.20, 7: 0.10, 8: 0.50, 0: 1.1,
    17: 1.0, 18: -0.03, 24: 7.5, 25: 1.0,
    16: 0.5, 15: 0.8, 19: 1.12
  }));
  seedSems.push(seedFrom({
    1: 0.5, 2: 0.45, 3: 0.45, 4: -0.45, 5: 0.15,
    6: -0.20, 7: 0.25, 8: 0.85, 0: 2.0,
    17: 2.0, 18: -0.08, 24: 6.5, 25: 0.8,
    16: 0.8, 15: 1.2, 13: 3.0, 19: 1.10
  }));
  seedSems.push(seedFrom({
    13: -2.5, 14: -0.5, 24: 7.0, 25: 1.0
  }));
  seedSems.push(seedFrom({
    1: 0.0, 2: 0.45, 3: 0.35, 4: -0.35, 5: 0.10,
    6: -0.20, 7: 0.35, 8: 1.0, 0: 2.2,
    17: 2.5, 18: -0.06, 24: 6.0, 25: 0.6,
    13: 3.0, 15: 1.5, 16: 1.0, 19: 1.10
  }));
  seedSems.push(seedFrom({
    1: 0.5, 2: 0.75, 3: 0.15, 4: -0.15, 5: 0.0,
    6: -0.15, 7: 0.05, 8: 0.40, 0: 0.9,
    17: 0.6, 18: -0.02, 24: 8.0, 25: 0.8,
    15: 1.0, 19: 1.13
  }));
  seedSems.push(seedFrom({
    1: 0.5, 2: 0.45, 3: 0.45, 4: -0.45, 5: 0.15,
    6: -0.20, 7: 0.25, 8: 0.85, 0: 2.0,
    17: 2.0, 18: -0.08, 24: 6.5, 25: 0.8,
    16: 0.8, 15: 1.2, 13: -3.0, 14: -0.5, 19: 1.10
  }));

  let seedItems = [];
  for (let i = 0; i < seedSems.length; i++) {
    let raw = semToRaw(seedSems[i]);
    seedItems.push(evalRaw(raw, null));
  }

  function baseSigma(i) {
    if (i <= 8) return 0.18;
    if (i <= 12) return 0.08;
    if (i >= 24 && i <= 28) return 0.08;
    return 0.12;
  }

  let specs = [
    { s: 0, mode: 0, sc: 0.9 },
    { s: 1, mode: 0, sc: 0.7 },
    { s: 2, mode: 1, sc: 1.1 },
    { s: 3, mode: 1, sc: 1.0 },
    { s: 4, mode: 2, sc: 1.0 },
    { s: 5, mode: 0, sc: 0.9 },
    { s: 6, mode: 1, sc: 1.2 },
    { s: 7, mode: 2, sc: 0.9 }
  ];

  let islands = [];
  for (let q = 0; q < specs.length; q++) {
    let sp = specs[q];
    let base = seedItems[sp.s] && seedItems[sp.s].raw
      ? seedItems[sp.s].raw.slice()
      : semToRaw(seedSems[sp.s]);
    let sig = new Array(D);
    for (let i = 0; i < D; i++) sig[i] = baseSigma(i) * sp.sc;
    let best = null, bestFit = -Infinity;
    if (seedItems[sp.s] && seedItems[sp.s].valid) {
      best = seedItems[sp.s];
      bestFit = fit(best, sp.mode);
    }
    islands.push({
      mean: base,
      sigma: sig,
      mode: sp.mode,
      best: best,
      bestFit: bestFit,
      stall: 0
    });
  }

  let gen = 0;
  while (used < 880 && remaining() > 80 && gen < 14) {
    for (let ii = 0; ii < islands.length; ii++) {
      if (used >= 880 || remaining() <= 80) break;
      let is = islands[ii];
      let N = 10;
      let cands = [];

      for (let j = 0; j < N && used < 880 && remaining() > 80; j++) {
        let x;
        if (j === 0) {
          x = is.mean.slice();
        } else {
          x = new Array(D);
          for (let i = 0; i < D; i++) {
            x[i] = clamp(is.mean[i] + is.sigma[i] * randn(), -1, 1);
          }
        }
        let item = evalRaw(x, null);
        if (item) {
          cands.push({ x: item.raw, item: item });
        }
      }

      if (!cands.length) continue;
      cands.sort(function (a, b) {
        return fit(b.item, is.mode) - fit(a.item, is.mode);
      });

      if (!is.best || !is.best.valid ||
          fit(cands[0].item, is.mode) > is.bestFit) {
        is.best = cands[0].item;
        is.bestFit = fit(cands[0].item, is.mode);
        is.stall = 0;
      } else {
        is.stall++;
      }

      let mu = Math.min(4, cands.length);
      let weights = [];
      let sumW = 0;
      for (let j = 0; j < mu; j++) {
        let w = Math.log(mu + 1) - Math.log(j + 1);
        weights.push(w);
        sumW += w;
      }
      if (sumW <= 0) sumW = 1;

      let newMean = new Array(D).fill(0);
      for (let j = 0; j < mu; j++) {
        let w = weights[j];
        let x = cands[j].x;
        for (let i = 0; i < D; i++) newMean[i] += w * x[i];
      }
      for (let i = 0; i < D; i++) newMean[i] /= sumW;

      let newSigma = new Array(D);
      for (let i = 0; i < D; i++) {
        let variance = 0;
        for (let j = 0; j < mu; j++) {
          let d = cands[j].x[i] - newMean[i];
          variance += weights[j] * d * d;
        }
        variance /= sumW;
        let sd = Math.sqrt(Math.max(0, variance)) + 0.01;
        newSigma[i] = clamp(sd, 0.015, 0.55);
      }

      for (let i = 0; i < D; i++) {
        is.mean[i] = clamp(0.2 * is.mean[i] + 0.8 * newMean[i], -1, 1);
        is.sigma[i] = clamp(0.2 * is.sigma[i] + 0.8 * newSigma[i], 0.015, 0.65);
      }

      if (is.stall > 3) {
        for (let i = 0; i < D; i++) {
          is.sigma[i] = Math.min(0.65, is.sigma[i] * 1.30 + 0.01);
        }
        if (is.best && is.best.raw) {
          is.mean = is.best.raw.slice();
        }
        is.stall = 0;
      }
    }
    gen++;
  }

  let validItems = all.filter(function (it) {
    return it && it.valid;
  });

  let finItems = validItems.filter(function (it) {
    return it.finished;
  });
  finItems.sort(function (a, b) { return b.dist - a.dist; });

  let allSorted = validItems.slice();
  allSorted.sort(function (a, b) { return b.dist - a.dist; });

  let candidateItems = [];
  let seenCand = Object.create(null);
  function addCand(it) {
    if (!it || !it.valid) return;
    let k = rawKey(it.raw);
    if (seenCand[k]) return;
    seenCand[k] = 1;
    candidateItems.push(it);
  }

  for (let i = 0; i < finItems.length && i < 10; i++) addCand(finItems[i]);
  for (let i = 0; i < allSorted.length && candidateItems.length < 18; i++) {
    addCand(allSorted[i]);
  }

  if (!candidateItems.length) {
    if (allSorted.length) return { v: allSorted[0].raw.slice() };
    return { v: DEFAULT_RAW.slice() };
  }

  let cands = candidateItems.map(function (it) {
    return { item: it, tests: [] };
  });

  let phases = [0.12, 0.27, 0.41];
  for (let i = 0; i < cands.length; i++) {
    for (let j = 0; j < phases.length; j++) {
      if (used >= MAX_TRIALS || remaining() <= 2) break;
      let it = evalRaw(cands[i].item.raw, { testPhase: phases[j] });
      if (it) cands[i].tests.push(it);
    }
  }

  function avgDist(c) {
    let s = scoreOf(c.item), n = 1;
    for (let i = 0; i < c.tests.length; i++) {
      s += scoreOf(c.tests[i]);
      n++;
    }
    return s / n;
  }

  cands.sort(function (a, b) { return avgDist(b) - avgDist(a); });

  let topForExtra = cands.slice(0, Math.min(8, cands.length));
  let heightOffs = [0.06, -0.06];
  for (let i = 0; i < topForExtra.length; i++) {
    for (let j = 0; j < heightOffs.length; j++) {
      if (used >= MAX_TRIALS || remaining() <= 2) break;
      let it = evalRaw(topForExtra[i].item.raw, { testHeight: heightOffs[j] });
      if (it) topForExtra[i].tests.push(it);
    }
  }

  let angleOffs = [0.05, -0.05];
  for (let i = 0; i < Math.min(4, topForExtra.length); i++) {
    for (let j = 0; j < angleOffs.length; j++) {
      if (used >= MAX_TRIALS || remaining() <= 2) break;
      let it = evalRaw(topForExtra[i].item.raw, { testAngle: angleOffs[j] });
      if (it) topForExtra[i].tests.push(it);
    }
  }

  let bestCand = null;
  let bestMetric = -Infinity;
  for (let i = 0; i < cands.length; i++) {
    let c = cands[i];
    let s = scoreOf(c.item), n = 1;
    for (let j = 0; j < c.tests.length; j++) {
      s += scoreOf(c.tests[j]);
      n++;
    }
    let avg = s / n;
    let bonus = c.item.finished ? 0.02 : 0;
    let metric = avg + bonus;
    if (metric > bestMetric) {
      bestMetric = metric;
      bestCand = c;
    }
  }

  if (!bestCand || !bestCand.item || !bestCand.item.raw) {
    return { v: (allSorted.length ? allSorted[0].raw.slice() : DEFAULT_RAW.slice()) };
  }
  return { v: bestCand.item.raw.slice() };
}

const BND = [
  [0.35, 2.8], [0.30, 0.90], [0.0, 0.65], [-0.25, 0.35], [-0.20, 0.40],
  [-0.55, -0.06], [0.0, 0.90], [0.10, 1.50], [-0.35, 0.15], [0.0, 3.50],
  [0.95, 1.25], [5, 80], [0.1, 6], [5, 100], [0.1, 8],
  [-25, 25], [-12, 12], [-10, 10],
  [-20, 20], [-12, 12],
  [-3, 3], [-3, 3], [0, 3], [-1, 2], [0, 1], [0.15, 1.2],
  [0, 1], [0, 2], [-0.3, 0.8], [0, 5],
  [0, 1], [-0.2, 0.2], [0, 0.8]
];
const D = BND.length;

function clamp(x, a, b) {
  return x < a ? a : (x > b ? b : x);
}
function smoothstep(u) {
  u = clamp(u, 0, 1);
  return u * u * (3 - 2 * u);
}

const DEF_SEM = [
  1.20, 0.66, 0.26, 0.03, 0.03,
  -0.14, 0.18, 0.70,
  -0.04, 0.55, 1.10,
  35, 1.2, 45, 1.8,
  5, 1.2, 1.2,
  4, 1.2,
  0.35, 0.5,
  1.0, 0.25,
  0.2, 0.5, 0.3, 0.7, 0.1, 1.0,
  0.5, 0.0, 0.1
];

function semToRaw(sem) {
  let out = new Array(D);
  for (let i = 0; i < D; i++) {
    let a = BND[i][0], b = BND[i][1];
    let v = sem[i];
    if (!isFinite(v)) v = (a + b) * 0.5;
    let r = 2 * (v - a) / (b - a) - 1;
    out[i] = clamp(r, -1, 1);
  }
  return out;
}

const DEFAULT_RAW = semToRaw(DEF_SEM);

function decodeParams(params) {
  let v = (params && params.v && params.v.length) ? params.v : null;
  let p = new Array(D);
  for (let i = 0; i < D; i++) {
    let x = (v && i < v.length && isFinite(v[i])) ? clamp(v[i], -1, 1) : DEFAULT_RAW[i];
    let a = BND[i][0], b = BND[i][1];
    p[i] = a + (x + 1) * 0.5 * (b - a);
  }
  return p;
}

let GSTAT = null;

function policy(obs, params, mem) {
  mem = mem || {};

  if (!mem.init) {
    mem.init = 1;
    mem.p = decodeParams(params);
    mem.startT = obs[19] || 0;
    mem.lastT = mem.startT;
    mem.phase = mem.p[1] * 0.5 + mem.p[31];
    if (params && isFinite(params.testPhase)) mem.phase += params.testPhase;
    mem.phase -= Math.floor(mem.phase);
    mem.vxF = obs[2] || 0;
    mem.prevCA = obs[9] > 0.5;
    mem.prevCB = obs[14] > 0.5;
    mem.angleBias = (params && isFinite(params.testLean)) ? params.testLean : 0;
    mem.heightBias = (params && isFinite(params.testHeight)) ? params.testHeight : 0;
    mem.logX = 0;
  }

  let p = mem.p;
  let t = obs[19];
  let dt = t - mem.lastT;
