  [-0.30, 0.30],  // 3 hip bias
  [-0.60, -0.05], // 4 knee base
  [-0.50, 0.50],  // 5 stance knee swing
  [0.00, 1.50],   // 6 swing knee lift
  [-0.30, 0.20],  // 7 target lean
  [0.00, 3.00],   // 8 target speed
  [-0.25, 0.10],  // 9 height offset
  [0.00, 1.00],   // 10 phase offset
  [8, 120],       // 11 hip kp
  [0.1, 8],       // 12 hip kd
  [8, 140],       // 13 knee kp
  [0.1, 10],      // 14 knee kd
  [-30, 30],      // 15 balance angle
  [-18, 18],      // 16 balance spin
  [-12, 12],      // 17 balance velocity
  [0, 40],        // 18 height kp
  [0, 12],        // 19 height kd
  [0, 4],         // 20 obstacle knee lift
  [-1, 2],        // 21 obstacle hip
