    if (isFinite(e.testPhase)) s += "p" + e.testPhase.toFixed(5);
    if (isFinite(e.testLean)) s += "l" + e.testLean.toFixed(5);
    if (isFinite(e.testHeight)) s += "h" + e.testHeight.toFixed(5);
    if (isFinite(e.testFreq)) s += "f" + e.testFreq.toFixed(5);
