  }

  function evalRaw(raw, extra) {
    let v = new Array(D);
    for (let i = 0; i < D; i++) {
      let x = (raw && i < raw.length) ? raw[i] : DEFAULT_RAW[i];
      if (!isFinite(x)) x = DEFAULT_RAW[i];
      v[i] = clamp(x, -1, 1);
    }

    let key = (extra ? extraKey(extra) + "|" : "") + rawKey(v);
    if (cache[key]) return cache[key];
    if (used >= MAX_EVAL || remaining() <= 0) return null;

    let params = { v: v.slice() };
    if (extra) {
      for (let k in extra) params[k] = extra[k];
    }

    STAT = {
      n: 0, t: 0,
      maxA: 0, maxS: 0, maxVy: 0, maxVx: 0,
      minH: 99, maxH: 0,
      lateN: 0, sumVx: 0, sumT: 0, sumT2: 0,
      sumTVx: 0, sumAng: 0, sumTAng: 0
    };

    let res = null;
    try {
      res = lab.trial(params);
    } catch (e) {
      res = null;
    }
    let st = STAT;
    STAT = null;
    used++;

    let dist = 0;
    let outcome = "error";
    let time = 0;
    let energy = 0;

    if (res) {
      if (isFinite(res.distance)) dist = Math.max(0, res.distance);
      if (res.outcome) outcome = String(res.outcome);
      if (isFinite(res.time)) time = clamp(res.time, 0, 10);
      if (isFinite(res.energy)) energy = res.energy;
    }
    if (time <= 0 && st && isFinite(st.t)) time = clamp(st.t, 0, 10);

    let valid = !!(res && outcome !== "invalid" && outcome !== "error");
    let finished = valid && (outcome === "finished" || (time >= 9.90 && outcome !== "fell"));

