    }

    if (sumW <= 0) continue;
    let avgPred = sumPred / sumW;
    let finFrac = finW / sumW;
    let avgRisk = riskW / sumW;
    let basePred = predOf(info.base);

    let metric = basePred * 2.0 + avgPred * 3.0 + minPred * 1.8;
    metric += finFrac * 3.0 - avgRisk * 0.35;
    if (!info.base || !info.base.finished) metric -= 0.25;

    if (metric > bestMetric) {
      bestMetric = metric;
      chosen = info.base;
    }
  }

  if (!chosen || !chosen.raw) {
    let sorted = validAll();
    if (!sorted.length) sorted = all.filter(function (it) { return it && it.valid; });
    sorted.sort(function (a, b) {
      return (b.pred + b.dist * 0.5 - b.risk * 0.1) -
             (a.pred + a.dist * 0.5 - a.risk * 0.1);
    });
    if (sorted.length) chosen = sorted[0];
  }

  STAT = null;
  if (!chosen || !chosen.raw) return { v: DEFAULT_RAW.slice() };
  return { v: chosen.raw.slice() };
}

function clamp(x,a,b){return x<a?a:(x>b?b:x);}
function smoothstep(u){u=clamp(u,0,1);return u*u*(3-2*u);}

const L1=0.42, L2=0.41, MAXL=L1+L2, TH=0.29;
const BND=[
 [0.35,2.90],  // 0 frequency
 [0.35,0.85],  // 1 duty
 [0.00,0.65],  // 2 stride
 [0.00,1.00],  // 3 phase offset
 [0.95,1.30],  // 4 target torso height
 [-0.28,0.24], // 5 target lean
 [0.00,0.32],  // 6 swing lift
 [0.00,3.00],  // 7 target speed
 [-12,12],     // 8 balance angle gain
 [-5,5],       // 9 balance spin gain
 [-6,6],       // 10 balance velocity gain
 [10,230],     // 11 hip kp
 [0.2,18],     // 12 hip kd
 [10,260],     // 13 knee kp
 [0.2,20],     // 14 knee kd
 [0.0,2.5],    // 15 height kp
 [0.0,1.5],    // 16 height kd
 [-0.5,0.5],   // 17 foot velocity placement
 [-0.4,0.4],   // 18 foot angle placement
 [-0.3,0.3],   // 19 foot spin placement
 [-0.2,0.2],   // 20 foot x bias
 [0.0,1.0],    // 21 start phase
 [0.0,1.5],    // 22 contact resync
 [0.0,2.5],    // 23 obstacle lift gain
 [0.0,0.35],   // 24 obstacle height gain
 [0.0,0.8]     // 25 terrain drop extension
];
const D=BND.length;
const DEF_SEM=[
 1.50,0.62,0.30,0.50,1.10,-0.04,0.12,1.20,
 2.50,0.80,0.50,90,4.0,110,4.5,0.80,0.25,
 0.12,-0.08,-0.02,0.00,0.08,0.25,0.80,0.08,0.35
];

function semToRaw(sem){
 let out=new Array(D);
 for(let i=0;i<D;i++){
  let a=BND[i][0],b=BND[i][1];
  let v=(sem&&isFinite(sem[i]))?sem[i]:(a+b)*0.5;
  out[i]=clamp(2*(v-a)/(b-a)-1,-1,1);
 }
 return out;
}
const DEFAULT_RAW=semToRaw(DEF_SEM);

function decodeParams(params){
 let v=(params&&params.v&&params.v.length)?params.v:null;
 let p=new Array(D);
 for(let i=0;i<D;i++){
  let x=(v&&i<v.length&&isFinite(v[i]))?clamp(v[i],-1,1):DEFAULT_RAW[i];
  let a=BND[i][0],b=BND[i][1];
  p[i]=a+(x+1)*0.5*(b-a);
 }
 return p;
}

function ik2(x,d){
 let r=Math.sqrt(x*x+d*d);
 r=clamp(r,0.18,MAXL-0.004);
 let phi=Math.atan2(x,d);
 let ck=(r*r-L1*L1-L2*L2)/(2*L1*L2);
 ck=clamp(ck,-1,1);
 let delta=Math.acos(ck);
 let k=-delta;
 let beta=Math.atan2(L2*Math.sin(delta),L1+L2*Math.cos(delta));
 let h=phi+beta;
 return [h,k];
}

let STAT=null;

function policy(obs,params,mem){
 mem=mem||{};
 obs=obs||[];

 if(!mem.init){
  mem.init=1;
  mem.p=decodeParams(params);
  mem.startT=isFinite(obs[19])?obs[19]:0;
  mem.lastT=mem.startT;
  mem.h0=isFinite(obs[4])?obs[4]:1.12;
  mem.hip0=[isFinite(obs[5])?obs[5]:0,isFinite(obs[10])?obs[10]:0];
  mem.knee0=[isFinite(obs[7])?obs[7]:-0.1,isFinite(obs[12])?obs[12]:-0.1];
  let ph=mem.p[21];
  if(params&&isFinite(params.testPhase)) ph+=params.testPhase;
  mem.phase=ph-Math.floor(ph);
  mem.freqBias=(params&&isFinite(params.testFreq))?params.testFreq:0;
  mem.leanBias=(params&&isFinite(params.testLean))?params.testLean:0;
  mem.heightBias=(params&&isFinite(params.testHeight))?params.testHeight:0;
  mem.speedBias=(params&&isFinite(params.testSpeed))?params.testSpeed:0;
  mem.vxF=isFinite(obs[2])?obs[2]:0;
  mem.x=0;
  mem.prevA=obs[9]>0.5;
  mem.prevB=obs[14]>0.5;
 }

 let p=mem.p;
 let t=isFinite(obs[19])?obs[19]:mem.lastT;
 let dt=t-mem.lastT;
 if(!(dt>0)||dt>0.3) dt=1/60;
 mem.lastT=t;

 let angle=isFinite(obs[0])?obs[0]:0;
 let spin=isFinite(obs[1])?obs[1]:0;
 let vx=isFinite(obs[2])?obs[2]:0;
 let vy=isFinite(obs[3])?obs[3]:0;
 let height=isFinite(obs[4])?obs[4]:mem.h0;
 let ca=obs[9]>0.5;
 let cb=obs[14]>0.5;
 let evA=ca&&!mem.prevA;
 let evB=cb&&!mem.prevB;

 let alpha=1-Math.exp(-dt/0.08);
 if(!isFinite(alpha)) alpha=0.1;
 mem.vxF+=alpha*(vx-mem.vxF);
 if(!isFinite(mem.vxF)) mem.vxF=vx;
 if(t>mem.startT) mem.x+=vx*dt;

 let duty=clamp(p[1],0.32,0.88);

 if(p[22]>0 && t-mem.startT>0.45){
  let adj=0,cnt=0;
  if(evA){
   let q=mem.phase-Math.floor(mem.phase);
   if(q>duty){
    let e=q; if(e>0.5)e-=1;
    adj-=e; cnt++;
   }
  }
  if(evB){
   let q=mem.phase+p[3]; q-=Math.floor(q);
   if(q>duty){
    let e=q; if(e>0.5)e-=1;
    adj-=e; cnt++;
   }
  }
  if(cnt>0){
   mem.phase+=p[22]*0.5*(adj/cnt);
   mem.phase-=Math.floor(mem.phase);
  }
 }

 let a1=isFinite(obs[15])?obs[15]:0;
 let a2=isFinite(obs[16])?obs[16]:0;
 let a3=isFinite(obs[17])?obs[17]:0;
 let a4=isFinite(obs[18])?obs[18]:0;
 let obst=Math.max(0,a1,0.90*a2,0.75*a3,0.50*a4);
 obst=clamp(obst,0,1.5);
 let dropAhead=Math.max(0,-a1,-0.90*a2,-0.75*a3,-0.50*a4);
 dropAhead=clamp(dropAhead,0,0.8);

 let ramp=smoothstep(clamp((t-mem.startT)/0.65,0,1));
 let freq=p[0]+0.04*Math.max(0,mem.vxF)+mem.freqBias;
 freq=clamp(freq,0.25,3.5);

 let Ht=clamp(p[4]+mem.heightBias+p[24]*obst,0.86,1.35);
 let targetSpeed=Math.max(0,p[7]+mem.speedBias);
 let leanT=p[5]+mem.leanBias;
 let hErr=Ht-height;
 let dCorr=clamp(p[15]*hErr-p[16]*vy,-0.18,0.25);
 let baseDrop=clamp(Ht-TH+dCorr+p[25]*dropAhead,0.34,MAXL-0.003);

 let angErr=angle-leanT;
 let bal=clamp(p[8]*angErr+p[9]*spin+p[10]*(mem.vxF-targetSpeed),-5,5);
 let footFb=clamp(p[17]*(mem.vxF-targetSpeed)+p[18]*angle+p[19]*spin+p[20],-0.35,0.35);

 let out=[0,0,0,0];

 for(let leg=0;leg<2;leg++){
  let off=leg?p[3]:0;
  let q=mem.phase+off;
  q-=Math.floor(q);

  let stance=q<duty;
  let x=0,lift=0;

  if(stance){
   let u=clamp(q/Math.max(1e-6,duty),0,1);
   x=p[2]*(0.5-u);
  }else{
   let u=clamp((q-duty)/Math.max(1e-6,1-duty),0,1);
   let sm=u*u*(3-2*u);
   x=p[2]*(-0.5+sm);
   lift=(p[6]+p[23]*obst)*Math.sin(Math.PI*u);
  }

  x=x*ramp+footFb*ramp;
  lift=lift*ramp;

  let drop=baseDrop-lift;
  let c=Math.cos(angle),s=Math.sin(angle);
  let xb=x*c-drop*s;
  let db=x*s+drop*c;
  if(db<0.16) db=0.16;

  let rr=Math.sqrt(xb*xb+db*db);
  if(rr>MAXL-0.002){
   let sc=(MAXL-0.002)/rr;
   xb*=sc; db*=sc;
  }

  let sol=ik2(xb,db);
  let hDes=clamp(sol[0],-0.88,1.18);
  let kDes=clamp(sol[1],-1.68,-0.055);

  hDes=mem.hip0[leg]+ramp*(hDes-mem.hip0[leg]);
  kDes=mem.knee0[leg]+ramp*(kDes-mem.knee0[leg]);

  let hp=isFinite(obs[leg?10:5])?obs[leg?10:5]:0;
  let hs=isFinite(obs[leg?11:6])?obs[leg?11:6]:0;
  let kn=isFinite(obs[leg?12:7])?obs[leg?12:7]:-0.1;
  let ks=isFinite(obs[leg?13:8])?obs[leg?13:8]:0;
  let contact=leg?cb:ca;

  let uHip=p[11]*(hDes-hp)-p[12]*hs;
  let uKnee=p[13]*(kDes-kn)-p[14]*ks;

  let bw=stance?1.0:0.45;
  if(!contact) bw*=0.70;
  uHip+=bal*bw;

  let emg=0;
  if(t-mem.startT>0.5){
   let aa=Math.abs(angle);
   if(aa>0.55) emg=Math.max(emg,clamp((aa-0.55)*4,0,2));
   if(height<0.65) emg=Math.max(emg,clamp((0.65-height)*5,0,2));
  }
  if(emg>0){
   uHip+=clamp(angle*8,-4,4)*emg;
   if(height<0.70) uKnee+=clamp((0.70-height)*4,0,1.5);
  }

  if(!isFinite(uHip)) uHip=0;
  if(!isFinite(uKnee)) uKnee=0;

  out[2*leg]=clamp(uHip,-1,1);
  out[2*leg+1]=clamp(uKnee,-1,1);
 }

 mem.phase+=freq*dt;
 mem.phase-=Math.floor(mem.phase);
 if(!isFinite(mem.phase)) mem.phase=0;

 if(STAT){
  STAT.n++;
  STAT.t=t;
  STAT.x=mem.x;
  if(ca)STAT.cA++;
  if(cb)STAT.cB++;
  if(!ca&&!cb)STAT.air++;
  if(evA)STAT.evA++;
  if(evB)STAT.evB++;

  let mj=Math.max(
   Math.abs(isFinite(obs[6])?obs[6]:0),
   Math.abs(isFinite(obs[8])?obs[8]:0),
   Math.abs(isFinite(obs[11])?obs[11]:0),
   Math.abs(isFinite(obs[13])?obs[13]:0)
  );
  if(mj>STAT.maxJoint) STAT.maxJoint=mj;

  if(t>0.5){
   let aa=Math.abs(angle); if(aa>STAT.maxA)STAT.maxA=aa;
   let as=Math.abs(spin); if(as>STAT.maxS)STAT.maxS=as;
   let av=Math.abs(vy); if(av>STAT.maxVy)STAT.maxVy=av;
   let ax=Math.abs(vx); if(ax>STAT.maxVx)STAT.maxVx=ax;
   if(height<STAT.minH)STAT.minH=height;
   if(height>STAT.maxH)STAT.maxH=height;
  }
  if(t>6.0){
   STAT.lateN++;
   STAT.sumVx+=vx;
   STAT.sumT+=t;
   STAT.sumT2+=t*t;
   STAT.sumTVx+=t*vx;
   STAT.sumAng+=angle;
   STAT.sumTAng+=t*angle;
   STAT.sumH+=height;
   STAT.sumTH+=t*height;
  }
 }

 mem.prevA=ca;
 mem.prevB=cb;
 return out;
}

function learn(lab){
 const MAX_EVAL=992;
 let used=0;
 let cache=Object.create(null);
 let all=[];

 function remaining(){
  try{if(lab&&lab.trialsLeft)return lab.trialsLeft();}catch(e){}
  return MAX_EVAL-used;
 }
 function randn(){
  let u=0,v=0;
  while(u===0)u=Math.random();
  while(v===0)v=Math.random();
  return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v);
 }
 function rawKey(v){
  let s="";
  for(let i=0;i<D;i++)s+=v[i].toFixed(5)+",";
  return s;
 }
 function extraKey(e){
  if(!e)return "";
  let s="";
  if(isFinite(e.testPhase))s+="p"+e.testPhase.toFixed(5);
  if(isFinite(e.testLean))s+="l"+e.testLean.toFixed(5);
  if(isFinite(e.testHeight))s+="h"+e.testHeight.toFixed(5);
  if(isFinite(e.testFreq))s+="f"+e.testFreq.toFixed(5);
  if(isFinite(e.testSpeed))s+="s"+e.testSpeed.toFixed(5);
  return s;
 }

 function evalRaw(raw,extra){
  let v=new Array(D);
  for(let i=0;i<D;i++){
   let x=(raw&&i<raw.length)?raw[i]:DEFAULT_RAW[i];
   if(!isFinite(x))x=DEFAULT_RAW[i];
   v[i]=clamp(x,-1,1);
  }
  let key=(extra?extraKey(extra)+"|":"")+rawKey(v);
  if(cache[key])return cache[key];
  if(used>=MAX_EVAL||remaining()<=0)return null;

  let params={v:v.slice()};
  if(extra)for(let k in extra)params[k]=extra[k];

  STAT={
   n:0,t:0,x:0,
   cA:0,cB:0,air:0,evA:0,evB:0,
   maxA:0,maxS:0,maxVy:0,maxVx:0,minH:99,maxH:0,maxJoint:0,
   lateN:0,sumVx:0,sumT:0,sumT2:0,sumTVx:0,
   sumAng:0,sumTAng:0,sumH:0,sumTH:0
  };

  let res=null;
  try{res=lab.trial(params);}catch(e){res=null;}
  let st=STAT;
  STAT=null;
  used++;

  let dist=0,outcome="error",time=0,energy=0;
  if(res){
   if(isFinite(res.distance))dist=Math.max(0,res.distance);
   if(res.outcome)outcome=String(res.outcome);
   if(isFinite(res.time))time=clamp(res.time,0,10);
   if(isFinite(res.energy))energy=res.energy;
  }
  if(time<=0&&st&&isFinite(st.t))time=clamp(st.t,0,10);

  let valid=!!(res&&outcome!=="invalid"&&outcome!=="error");
  let finished=valid&&(outcome==="finished"||(time>=9.85&&outcome!=="fell"));

  let signed=(st&&isFinite(st.x))?st.x:0;
  if(!st||st.n===0)signed=dist;
  let fwd=Math.max(0,signed);
  let back=Math.max(0,-signed);

  let lateN=st?st.lateN:0;
  let lateMean=0,lateSlope=0,hSlope=0,angMean=0,angSlope=0;
  if(lateN>0){
   lateMean=st.sumVx/lateN;
   angMean=st.sumAng/lateN;
   if(lateN>2){
    let den=lateN*st.sumT2-st.sumT*st.sumT;
    if(Math.abs(den)>1e-9){
     lateSlope=(lateN*st.sumTVx-st.sumT*st.sumVx)/den;
     hSlope=(lateN*st.sumTH-st.sumT*st.sumH)/den;
     angSlope=(lateN*st.sumTAng-st.sumT*st.sumAng)/den;
    }
   }
  }

  let risk=0;
  if(!valid){
   risk=100;
  }else if(st){
   risk+=Math.max(0,st.maxA-0.65)*8.0;
   let minH=(st.minH<50)?st.minH:0.6;
   risk+=Math.max(0,0.72-minH)*20.0;
   risk+=Math.max(0,st.maxS-8.0)*0.5;
   risk+=Math.max(0,st.maxVy-4.5)*0.4;
   risk+=Math.max(0,st.maxJoint-18.0)*0.15;
   if(lateMean<-0.03)risk+=(-lateMean-0.03)*8.0;
   if(lateSlope<-0.08)risk+=(-lateSlope-0.08)*30.0;
   if(hSlope<-0.005)risk+=(-hSlope-0.005)*30.0;
   if(Math.abs(angMean)>0.25)risk+=(Math.abs(angMean)-0.25)*8.0;
   if(Math.abs(angSlope)>0.15)risk+=(Math.abs(angSlope)-0.15)*20.0;
  }
  if(!finished)risk+=Math.max(0,9.8-time)*1.5;
  if(back>0.1)risk+=back*0.8;

  let pred=fwd;
  if(finished)pred+=Math.max(0,Math.min(3.5,lateMean))*10.0;

  let item={
   raw:v.slice(),signed:signed,fwd:fwd,dist:dist,outcome:outcome,time:time,
   energy:energy,valid:valid,finished:finished,risk:risk,
   lateMean:lateMean,lateSlope:lateSlope,hSlope:hSlope,
   angMean:angMean,angSlope:angSlope,pred:pred,
   extra:!!extra,extraSpec:extra?Object.assign({},extra):null
  };
  cache[key]=item;
  all.push(item);
  return item;
 }

 function fitItem(it,mode){
  if(!it||!it.valid)return -1e12;
  let f=it.fwd,p=it.pred,r=it.risk,fin=it.finished?1:0,tm=it.time;
  let late=Math.max(0,Math.min(3.5,it.lateMean));
  if(mode===0)return p*12+f*8+fin*30+late*20-r*4;
  if(mode===1)return fin*200+p*8+f*4-r*10;
  if(mode===2)return f*30+p*6+fin*10-r*2;
  if(mode===3)return fin*100+p*15+f*2-r*15;
  if(mode===4)return p*20+Math.max(0,it.signed)*10+fin*5-r*3;
  return fin*50+f*12+p*10+late*30-r*5;
 }

 function preMetric(it){
  if(!it||!it.valid)return -1e12;
  let f=it.fwd,p=it.pred,r=it.risk,fin=it.finished?1:0;
  let late=Math.max(0,Math.min(3.5,it.lateMean));
  let s=f*10+p*6+fin*30+late*25-r*6;
  if(it.signed<0.05)s-=2;
  return s;
 }

 function validAll(){
  return all.filter(function(it){return it&&it.valid&&!it.extra;});
 }

 function makeSeed(over){
  let sem=DEF_SEM.slice();
  if(over){
   for(let k in over){
    let idx=+k;
    if(idx>=0&&idx<D&&isFinite(over[k]))sem[idx]=over[k];
   }
  }
  return semToRaw(sem);
 }

 function randomRaw(){
  let x=new Array(D);
  for(let i=0;i<D;i++)x[i]=Math.random()*2-1;
  return x;
 }

