// ---- Brain: rhythm generator + PD servos + torso balance feedback ----
function policy(obs, params, mem) {
  const p = params || {};
  const dt = 1 / 60;
  if (mem.ph === undefined) mem.ph = 0;
  const o = i => (typeof obs[i] === 'number' && isFinite(obs[i])) ? obs[i] : 0;

  mem.ph += (p.freq || 6) * dt;

  const lean = o(0), spin = o(1), vx = o(2);
  const hipC = (p.hipCenter || 0) + (p.balHip || 0) * lean
             + (p.balSpin || 0) * spin + (p.balVel || 0) * vx;

  // obstacle ahead (ground higher than under torso, metres) -> lift knees more
  const h = clamp(o(15) / 0.25, 0, 1);
  const kAmp = clamp((p.kneeAmp || 0) + (p.hurdleK || 0) * h, 0, 1.3);

  const kp = p.kp || 8, kd = p.kd || 0.5;
  const out = [];
  const legs = [[5, 0], [10, p.legOffset || 0]];
  for (const [base, off] of legs) {
    const ph = mem.ph + off;
    const hipT = clamp(hipC + (p.hipAmp || 0) * Math.sin(ph), -0.9, 1.2);
    const bend = 0.5 - 0.5 * Math.cos(ph + (p.kneePhase || 0)); // 0..1
    const kneeT = clamp((p.kneeCenter || -0.5) - kAmp * bend, -1.7, -0.05);
    const hip = o(base), hipV = o(base + 1), knee = o(base + 2), kneeV = o(base + 3);
    const uh = clamp(kp * (hipT - hip) - kd * hipV, -1, 1);
    const uk = clamp(kp * (kneeT - knee) - kd * kneeV, -1, 1);
    out.push(uh, uk);
  }
  return out;
}

// ---- Learner: random seeds + (1+1)-ES on distance ----
function learn(lab) {
  // [name, lo, hi, init]
  const SPEC = [
    ['freq',        3,     12,    6.0],
    ['hipAmp',      0.1,   0.9,   0.45],
    ['hipCenter',   -0.3,  0.4,   0.1],
    ['kneeCenter',  -1.2,  -0.1,  -0.5],
    ['kneeAmp',     0,     0.9,   0.4],
    ['kneePhase',   -3.14, 3.14,  0.0],
    ['legOffset',   0,     6.283, 3.1416],
    ['balHip',      -3,    3,     0.5],
    ['balSpin',     -0.6,  0.6,   0.1],
    ['balVel',      -0.5,  0.5,   0.0],
    ['kp',          3,     15,    8],
    ['kd',          0.1,   1.5,   0.5],
    ['hurdleK',     0,     0.8,   0.3]
  ];
  const n = SPEC.length;
  const t0 = (typeof Date !== 'undefined' && Date.now) ? Date.now() : 0;
  const elapsed = () => (typeof Date !== 'undefined' && Date.now) ? (Date.now() - t0) / 1000 : 0;

  const decode = x => {
    const p = {};
    SPEC.forEach((s, i) => { p[s[0]] = s[1] + x[i] * (s[2] - s[1]); });
    return p;
  };
  const gauss = () => {
    let u = 0;
    while (u === 0) u = Math.random();
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const clamp01 = v => clamp(v, 0, 1);
  const randomX = () => SPEC.map(() => Math.random());

  let bestF = -Infinity, bestParams = null;

  const evalX = x => {
    if (lab.trialsLeft() <= 0) return null;
    let r;
    try { r = lab.trial(decode(x)); } catch (e) { return -1; }
    let f = -1;
    if (r && r.outcome !== 'invalid' && r.outcome !== 'error' && isFinite(r.distance)) f = r.distance;
    if (f > bestF) { bestF = f; bestParams = decode(x); }
    return f;
  };

  try {
    // seed: hand-designed centre point
    const xInit = SPEC.map(s => clamp01((s[3] - s[1]) / (s[2] - s[1])));
    let x = xInit.slice();
    let f = evalX(x);
    if (f === null) return bestParams || decode(xInit);

    // random exploration
    for (let k = 0; k < 25 && lab.trialsLeft() > 0 && elapsed() < 90; k++) {
      const c = randomX();
      const fc = evalX(c);
      if (fc === null) break;
      if (fc > f) { x = c; f = fc; }
    }

    // (1+1)-ES with 1/5-ish step adaptation and periodic restarts
    let sigma = 0.15, noImp = 0;
    while (lab.trialsLeft() > 0 && elapsed() < 150) {
      let cand;
      if (noImp > 80) {
        cand = randomX();
        noImp = 0;
        sigma = 0.2;
      } else {
        cand = x.map(v => clamp01(v + sigma * gauss()));
      }
      const fc = evalX(cand);
      if (fc === null) break;
      if (fc > f) {
        x = cand; f = fc;
        sigma = Math.min(0.4, sigma * 1.4);
        noImp = 0;
      } else {
        sigma = Math.max(0.01, sigma * 0.93);
        noImp++;
      }
    }
  } catch (e) {
    // fall through and return best found so far
  }

  return bestParams || decode(SPEC.map(s => clamp01((s[3] - s[1]) / (s[2] - s[1]))));
}

