function policy(obs, params, mem) {
  const P = params || {};
  const num = (k, d) => (typeof P[k] === 'number' && isFinite(P[k])) ? P[k] : d;
  const o = i => (typeof obs[i] === 'number' && isFinite(obs[i])) ? obs[i] : 0;
  if (typeof mem.ph !== 'number') mem.ph = 0;
  mem.ph += num('freq', 6) / 60;

  const lean = o(0), spin = o(1), vx = o(2), hgt = o(4);
  const hipC = num('hipCenter', 0) + num('balHip', 0) * lean
             + num('balSpin', 0) * spin + num('balVel', 0) * vx;
  const hz = clamp(o(15) / 0.25, 0, 1);
  const kAmp = clamp(num('kneeAmp', 0) + num('hurdleK', 0) * hz, 0, 1.3);
  // torso height feedback: low torso -> straighten knees
  const kC = num('kneeCenter', -0.5) + num('hgtK', 0) * (num('hgtRef', 0.9) - hgt);
  const kp = num('kp', 8), kd = num('kd', 0.5);
  const hipAmp = num('hipAmp', 0.45), kneePhase = num('kneePhase', 0);
  const legs = [
    { b: 5, off: 0, f: 9 },
    { b: 10, off: num('legOffset', Math.PI), f: 14 }
  ];
  const out = [];
  for (const L of legs) {
    const ph = mem.ph + L.off;
    const contact = o(L.f) > 0.5;
    let hipT = hipC + hipAmp * Math.sin(ph) + (contact ? num('contactHip', 0) : 0);
    hipT = clamp(hipT, -0.9, 1.2);
    const bend = 0.5 - 0.5 * Math.cos(ph + kneePhase); // 0..1
    let kneeT = kC - kAmp * bend + (contact ? num('contactKnee', 0) : 0);
    kneeT = clamp(kneeT, -1.7, -0.05);
    const hip = o(L.b), hipV = o(L.b + 1), knee = o(L.b + 2), kneeV = o(L.b + 3);
    const uh = clamp(kp * (hipT - hip) - kd * hipV, -1, 1);
    const uk = clamp(kp * (kneeT - knee) - kd * kneeV, -1, 1);
    out.push(uh, uk);
  }
  return out;
}

