    const base = seedX();
    const f0 = evalX(base);
    if (f0 === null) return bestP || toP(base);

    let cur = base.slice();
    let fc = f0;
    let sigma = 0.05;
    const LAM = 8;
    let gens = 0;

    while (lab.trialsLeft() > 0 && !timeUp()) {
      let genBest = null, genF = -Infinity;
      for (let k = 0; k < LAM; k++) {
        if (lab.trialsLeft() <= 0 || timeUp()) break;
        const x = cur.map(v => clamp01(v + sigma * gauss()));
        const f = evalX(x);
        if (f === null) break;
        if (f > genF) { genF = f; genBest = x; }
      }
      gens++;
      if (genBest !== null && genF >= fc) {
        const improved = genF > fc + 1e-9;
        cur = genBest;
        fc = genF;
        sigma = clamp(sigma * (improved ? 1.25 : 1.0), 0.005, 0.15);
      } else {
        sigma *= 0.85;
      }
      // restart the step size if the search has collapsed
      if (sigma < 0.006) sigma = 0.04;
    }
  } catch (e) {
    // fall through and return best found so far
  }

  return bestP || toP(seedX());
}
